        assert_eq!(actual, expected);
    }
    for text in ["256", "511", "-1", "18446744073709551615"] {
        assert!(simd_json::serde::from_slice::<u8>(&mut text.as_bytes().to_vec()).is_err(), "u8 accepted {text}");
    }
    for (text, expected) in [("-128", -128i8), ("127", 127i8)] {
